def sq_tl(M,bg=9):
    out={}
    for i in range(M.shape[0]-1):
        for j in range(M.shape[1]-1):
            c=M[i,j]
            if c!=bg and M[i,j+1]==c and M[i+1,j]==c and M[i+1,j+1]==c:
                out[(i,j)]=c
    return out
t1={k:(k[0],k[1],v) for k,v in sq_tl(M1).items()}
