def drop(M,i,j,c,bg=9):
    # drop if square exists immediately left AND immediately below
    def sq(a,b):
        return 0<=a<M.shape[0]-1 and 0<=b<M.shape[1]-1 and M[a,b]==c and M[a,b+1]==c and M[a+1,b]==c and M[a+1,b+1]==c
    return sq(i,j-1) and sq(i+1,j)
def rule(M,bg=9):
    return {(i,j,c) for (i,j),c in sq_tl(M,bg).items() if not drop(M,i,j,c,bg)}
